CREATE TABLE IF NOT EXISTS companies (
  id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, name VARCHAR(160) NOT NULL, legal_name VARCHAR(190), slug VARCHAR(190) NOT NULL UNIQUE,
  logo_path VARCHAR(255), email VARCHAR(190), phone VARCHAR(40), address TEXT, city VARCHAR(100), state VARCHAR(100), postal_code VARCHAR(20), country CHAR(2) NOT NULL DEFAULT 'IN', gstin VARCHAR(20), pan VARCHAR(20), currency CHAR(3) NOT NULL DEFAULT 'INR', timezone VARCHAR(64) NOT NULL DEFAULT 'Asia/Kolkata', settings JSON,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS brands (
  id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, company_id BIGINT UNSIGNED NOT NULL, name VARCHAR(120) NOT NULL, slug VARCHAR(120) NOT NULL, primary_color CHAR(7) DEFAULT '#12304A', accent_color CHAR(7) DEFAULT '#20A596', logo_path VARCHAR(255), is_active BOOLEAN NOT NULL DEFAULT TRUE,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  UNIQUE KEY uq_brand_company_slug(company_id,slug), CONSTRAINT fk_brands_company FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS branches (
  id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, company_id BIGINT UNSIGNED NOT NULL, brand_id BIGINT UNSIGNED, name VARCHAR(120) NOT NULL, code VARCHAR(24) NOT NULL, email VARCHAR(190), phone VARCHAR(40), address TEXT, city VARCHAR(100), state VARCHAR(100), is_active BOOLEAN NOT NULL DEFAULT TRUE,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  UNIQUE KEY uq_branch_company_code(company_id,code), CONSTRAINT fk_branches_company FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE RESTRICT, CONSTRAINT fk_branches_brand FOREIGN KEY(brand_id) REFERENCES brands(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS users (
  id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, company_id BIGINT UNSIGNED NOT NULL, branch_id BIGINT UNSIGNED, name VARCHAR(160) NOT NULL, email VARCHAR(190) NOT NULL, phone VARCHAR(40), password_hash VARCHAR(255) NOT NULL, is_active BOOLEAN NOT NULL DEFAULT TRUE, last_login_at DATETIME,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  UNIQUE KEY uq_users_email(email), INDEX ix_users_company_branch(company_id,branch_id), CONSTRAINT fk_users_company FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE RESTRICT, CONSTRAINT fk_users_branch FOREIGN KEY(branch_id) REFERENCES branches(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS roles (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, company_id BIGINT UNSIGNED NOT NULL, name VARCHAR(80) NOT NULL, is_system BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_roles_company_name(company_id,name), CONSTRAINT fk_roles_company FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS permissions (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, name VARCHAR(120) NOT NULL UNIQUE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS role_permissions (role_id BIGINT UNSIGNED NOT NULL, permission_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY(role_id,permission_id), FOREIGN KEY(role_id) REFERENCES roles(id) ON DELETE CASCADE, FOREIGN KEY(permission_id) REFERENCES permissions(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS user_roles (user_id BIGINT UNSIGNED NOT NULL, role_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY(user_id,role_id), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(role_id) REFERENCES roles(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS user_branches (user_id BIGINT UNSIGNED NOT NULL, branch_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY(user_id,branch_id), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(branch_id) REFERENCES branches(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS auth_sessions (id CHAR(64) PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, expires_at DATETIME NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX ix_sessions_expiry(expires_at), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS numbering_sequences (company_id BIGINT UNSIGNED NOT NULL, sequence_key VARCHAR(32) NOT NULL, prefix VARCHAR(20) NOT NULL, next_value BIGINT UNSIGNED NOT NULL DEFAULT 1, PRIMARY KEY(company_id,sequence_key), FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS vehicle_categories (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, company_id BIGINT UNSIGNED NOT NULL, name VARCHAR(100) NOT NULL, slug VARCHAR(120) NOT NULL, default_seating_capacity SMALLINT UNSIGNED, is_active BOOLEAN DEFAULT TRUE, UNIQUE KEY uq_category_slug(company_id,slug), FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS vendors (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, company_id BIGINT UNSIGNED NOT NULL, branch_id BIGINT UNSIGNED, vendor_code VARCHAR(32) NOT NULL, name VARCHAR(190) NOT NULL, vendor_type VARCHAR(40) NOT NULL DEFAULT 'other', contact_name VARCHAR(160), phone VARCHAR(40), email VARCHAR(190), gstin VARCHAR(20), payment_terms_days SMALLINT UNSIGNED DEFAULT 0, status VARCHAR(20) DEFAULT 'active', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uq_vendor_code(company_id,vendor_code), FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE RESTRICT, FOREIGN KEY(branch_id) REFERENCES branches(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS drivers (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, company_id BIGINT UNSIGNED NOT NULL, branch_id BIGINT UNSIGNED, user_id BIGINT UNSIGNED UNIQUE, driver_code VARCHAR(32) NOT NULL, name VARCHAR(160) NOT NULL, phone VARCHAR(40) NOT NULL, license_number VARCHAR(80) NOT NULL, license_expires_at DATE, availability_status VARCHAR(24) NOT NULL DEFAULT 'available', employment_status VARCHAR(24) NOT NULL DEFAULT 'active', UNIQUE KEY uq_driver_code(company_id,driver_code), UNIQUE KEY uq_driver_license(company_id,license_number), FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE RESTRICT, FOREIGN KEY(branch_id) REFERENCES branches(id) ON DELETE SET NULL, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS staff_profiles (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, company_id BIGINT UNSIGNED NOT NULL, branch_id BIGINT UNSIGNED, user_id BIGINT UNSIGNED UNIQUE, employee_code VARCHAR(32) NOT NULL, name VARCHAR(160) NOT NULL, email VARCHAR(190), phone VARCHAR(40), employment_status VARCHAR(24) NOT NULL DEFAULT 'active', UNIQUE KEY uq_staff_code(company_id,employee_code), FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE RESTRICT, FOREIGN KEY(branch_id) REFERENCES branches(id) ON DELETE SET NULL, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS vehicles (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, company_id BIGINT UNSIGNED NOT NULL, branch_id BIGINT UNSIGNED, vehicle_category_id BIGINT UNSIGNED NOT NULL, assigned_driver_id BIGINT UNSIGNED, vendor_id BIGINT UNSIGNED, vehicle_code VARCHAR(32) NOT NULL, registration_number VARCHAR(32) NOT NULL, name VARCHAR(120) NOT NULL, model VARCHAR(100), manufacturer VARCHAR(100), seating_capacity SMALLINT UNSIGNED DEFAULT 4, fuel_type VARCHAR(24), odometer_km DECIMAL(11,1) NOT NULL DEFAULT 0, ownership_type VARCHAR(24) NOT NULL DEFAULT 'owned', default_rate_per_km DECIMAL(12,2) NOT NULL DEFAULT 0, vendor_rate_per_km DECIMAL(12,2) NOT NULL DEFAULT 0, minimum_billable_km INT UNSIGNED NOT NULL DEFAULT 0, status VARCHAR(24) NOT NULL DEFAULT 'available', insurance_expires_at DATE, permit_expires_at DATE, fitness_expires_at DATE, pollution_expires_at DATE, photo_path VARCHAR(255), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uq_vehicle_code(company_id,vehicle_code), UNIQUE KEY uq_vehicle_registration(company_id,registration_number), INDEX ix_vehicle_branch_status(company_id,branch_id,status), FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE RESTRICT, FOREIGN KEY(branch_id) REFERENCES branches(id) ON DELETE SET NULL, FOREIGN KEY(vehicle_category_id) REFERENCES vehicle_categories(id) ON DELETE RESTRICT, FOREIGN KEY(assigned_driver_id) REFERENCES drivers(id) ON DELETE SET NULL, FOREIGN KEY(vendor_id) REFERENCES vendors(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS vehicle_odometer_logs (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, company_id BIGINT UNSIGNED NOT NULL, vehicle_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED, previous_km DECIMAL(11,1) NOT NULL, recorded_km DECIMAL(11,1) NOT NULL, reason VARCHAR(255) NOT NULL, recorded_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX ix_odo_vehicle(vehicle_id,recorded_at), FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE RESTRICT, FOREIGN KEY(vehicle_id) REFERENCES vehicles(id) ON DELETE RESTRICT, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS customers (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, company_id BIGINT UNSIGNED NOT NULL, branch_id BIGINT UNSIGNED, assigned_user_id BIGINT UNSIGNED, customer_code VARCHAR(32) NOT NULL, customer_type VARCHAR(20) NOT NULL DEFAULT 'individual', name VARCHAR(160) NOT NULL, company_name VARCHAR(190), phone VARCHAR(40) NOT NULL, email VARCHAR(190), billing_address TEXT, city VARCHAR(100), state VARCHAR(100), gstin VARCHAR(20), credit_limit DECIMAL(14,2), payment_terms_days SMALLINT UNSIGNED NOT NULL DEFAULT 0, status VARCHAR(20) NOT NULL DEFAULT 'active', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uq_customer_code(company_id,customer_code), INDEX ix_customer_phone(company_id,phone), FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE RESTRICT, FOREIGN KEY(branch_id) REFERENCES branches(id) ON DELETE SET NULL, FOREIGN KEY(assigned_user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS customer_contacts (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, customer_id BIGINT UNSIGNED NOT NULL, name VARCHAR(160) NOT NULL, designation VARCHAR(100), phone VARCHAR(40), email VARCHAR(190), is_primary BOOLEAN DEFAULT FALSE, FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS enquiries (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, company_id BIGINT UNSIGNED NOT NULL, branch_id BIGINT UNSIGNED, customer_id BIGINT UNSIGNED, assigned_user_id BIGINT UNSIGNED, enquiry_number VARCHAR(40) NOT NULL, contact_name VARCHAR(160) NOT NULL, phone VARCHAR(40) NOT NULL, email VARCHAR(190), travel_at DATETIME, pickup_location VARCHAR(190) NOT NULL, destination VARCHAR(190) NOT NULL, passengers SMALLINT UNSIGNED DEFAULT 1, vehicle_category_id BIGINT UNSIGNED, trip_type VARCHAR(32) NOT NULL, source VARCHAR(60), status VARCHAR(24) NOT NULL DEFAULT 'new', notes TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_enquiry_no(company_id,enquiry_number), FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE RESTRICT, FOREIGN KEY(branch_id) REFERENCES branches(id) ON DELETE SET NULL, FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE SET NULL, FOREIGN KEY(assigned_user_id) REFERENCES users(id) ON DELETE SET NULL, FOREIGN KEY(vehicle_category_id) REFERENCES vehicle_categories(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS follow_ups (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, company_id BIGINT UNSIGNED NOT NULL, enquiry_id BIGINT UNSIGNED NOT NULL, assigned_user_id BIGINT UNSIGNED, due_at DATETIME NOT NULL, channel VARCHAR(24) NOT NULL, status VARCHAR(24) NOT NULL DEFAULT 'pending', notes TEXT, completed_at DATETIME, INDEX ix_followup_due(company_id,status,due_at), FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE RESTRICT, FOREIGN KEY(enquiry_id) REFERENCES enquiries(id) ON DELETE RESTRICT, FOREIGN KEY(assigned_user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS vehicle_rate_rules (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, company_id BIGINT UNSIGNED NOT NULL, branch_id BIGINT UNSIGNED, vehicle_category_id BIGINT UNSIGNED, vehicle_id BIGINT UNSIGNED, customer_id BIGINT UNSIGNED, trip_type VARCHAR(32), name VARCHAR(120) NOT NULL, effective_from DATE NOT NULL, effective_to DATE, rate_per_km DECIMAL(12,2) NOT NULL DEFAULT 0, minimum_billable_km INT UNSIGNED DEFAULT 0, minimum_trip_amount DECIMAL(12,2) DEFAULT 0, driver_allowance DECIMAL(12,2) DEFAULT 0, night_allowance DECIMAL(12,2) DEFAULT 0, outstation_allowance DECIMAL(12,2) DEFAULT 0, local_package_amount DECIMAL(12,2), extra_hour_rate DECIMAL(12,2) DEFAULT 0, waiting_rate_per_hour DECIMAL(12,2) DEFAULT 0, pickup_drop_charge DECIMAL(12,2) DEFAULT 0, one_way_surcharge DECIMAL(12,2) DEFAULT 0, advance_percent DECIMAL(5,2) DEFAULT 0, tax_rate_percent DECIMAL(5,2) DEFAULT 0, tax_tolls BOOLEAN DEFAULT FALSE, tax_parking BOOLEAN DEFAULT FALSE, is_active BOOLEAN DEFAULT TRUE, INDEX ix_rate_scope(company_id,branch_id,vehicle_category_id,effective_from), FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE RESTRICT, FOREIGN KEY(branch_id) REFERENCES branches(id) ON DELETE SET NULL, FOREIGN KEY(vehicle_category_id) REFERENCES vehicle_categories(id) ON DELETE SET NULL, FOREIGN KEY(vehicle_id) REFERENCES vehicles(id) ON DELETE SET NULL, FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS quotations (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, company_id BIGINT UNSIGNED NOT NULL, branch_id BIGINT UNSIGNED, customer_id BIGINT UNSIGNED NOT NULL, enquiry_id BIGINT UNSIGNED, created_by BIGINT UNSIGNED, quotation_number VARCHAR(40) NOT NULL, version SMALLINT UNSIGNED NOT NULL DEFAULT 1, status VARCHAR(24) NOT NULL DEFAULT 'draft', valid_until DATE, trip_type VARCHAR(32) NOT NULL, pickup_location VARCHAR(190) NOT NULL, destination VARCHAR(190) NOT NULL, travel_at DATETIME, estimated_km INT UNSIGNED NOT NULL, pricing_snapshot JSON NOT NULL, subtotal DECIMAL(14,2) NOT NULL, discount_amount DECIMAL(14,2) NOT NULL, tax_amount DECIMAL(14,2) NOT NULL, total_amount DECIMAL(14,2) NOT NULL, advance_required DECIMAL(14,2) NOT NULL, terms TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_quote_no(company_id,quotation_number), FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE RESTRICT, FOREIGN KEY(branch_id) REFERENCES branches(id) ON DELETE SET NULL, FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE RESTRICT, FOREIGN KEY(enquiry_id) REFERENCES enquiries(id) ON DELETE SET NULL, FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS quotation_items (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, quotation_id BIGINT UNSIGNED NOT NULL, description VARCHAR(190) NOT NULL, amount DECIMAL(14,2) NOT NULL, discount_amount DECIMAL(14,2) NOT NULL DEFAULT 0, tax_rate_percent DECIMAL(5,2) DEFAULT 0, tax_amount DECIMAL(14,2) NOT NULL DEFAULT 0, line_total DECIMAL(14,2) NOT NULL, FOREIGN KEY(quotation_id) REFERENCES quotations(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS bookings (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, company_id BIGINT UNSIGNED NOT NULL, branch_id BIGINT UNSIGNED, customer_id BIGINT UNSIGNED NOT NULL, quotation_id BIGINT UNSIGNED UNIQUE, vehicle_category_id BIGINT UNSIGNED, vehicle_id BIGINT UNSIGNED, driver_id BIGINT UNSIGNED, created_by BIGINT UNSIGNED, booking_number VARCHAR(40) NOT NULL, contact_name VARCHAR(160) NOT NULL, contact_phone VARCHAR(40) NOT NULL, pickup_at DATETIME NOT NULL, expected_return_at DATETIME NOT NULL, pickup_address VARCHAR(255) NOT NULL, destination VARCHAR(255) NOT NULL, trip_type VARCHAR(32) NOT NULL, expected_km INT UNSIGNED NOT NULL DEFAULT 0, passengers SMALLINT UNSIGNED NOT NULL DEFAULT 1, status VARCHAR(24) NOT NULL DEFAULT 'confirmed', pricing_snapshot JSON NOT NULL, quoted_total DECIMAL(14,2) NOT NULL, advance_received DECIMAL(14,2) NOT NULL DEFAULT 0, payment_terms VARCHAR(100), special_instructions TEXT, cancel_reason VARCHAR(255), confirmed_at DATETIME, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_booking_no(company_id,booking_number), INDEX ix_vehicle_booking(vehicle_id,status,pickup_at,expected_return_at), INDEX ix_driver_booking(driver_id,status,pickup_at,expected_return_at), FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE RESTRICT, FOREIGN KEY(branch_id) REFERENCES branches(id) ON DELETE SET NULL, FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE RESTRICT, FOREIGN KEY(vehicle_category_id) REFERENCES vehicle_categories(id) ON DELETE SET NULL, FOREIGN KEY(vehicle_id) REFERENCES vehicles(id) ON DELETE SET NULL, FOREIGN KEY(driver_id) REFERENCES drivers(id) ON DELETE SET NULL, FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS booking_rate_snapshots (booking_id BIGINT UNSIGNED PRIMARY KEY, rule_id BIGINT UNSIGNED, inputs JSON NOT NULL, calculation JSON NOT NULL, captured_at DATETIME NOT NULL, FOREIGN KEY(booking_id) REFERENCES bookings(id) ON DELETE RESTRICT, FOREIGN KEY(rule_id) REFERENCES vehicle_rate_rules(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS trips (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, company_id BIGINT UNSIGNED NOT NULL, branch_id BIGINT UNSIGNED, booking_id BIGINT UNSIGNED NOT NULL UNIQUE, vehicle_id BIGINT UNSIGNED NOT NULL, driver_id BIGINT UNSIGNED NOT NULL, trip_number VARCHAR(40) NOT NULL, status VARCHAR(24) NOT NULL DEFAULT 'in_progress', started_at DATETIME NOT NULL, completed_at DATETIME, odometer_start DECIMAL(12,1) NOT NULL, odometer_end DECIMAL(12,1), actual_km DECIMAL(12,1), billable_km DECIMAL(12,1), approval_status VARCHAR(24) NOT NULL DEFAULT 'pending', pricing_snapshot JSON, subtotal DECIMAL(14,2) DEFAULT 0, discount_amount DECIMAL(14,2) DEFAULT 0, tax_amount DECIMAL(14,2) DEFAULT 0, total_amount DECIMAL(14,2) DEFAULT 0, driver_notes TEXT, UNIQUE KEY uq_trip_number(company_id,trip_number), INDEX ix_trip_vehicle(vehicle_id,status), FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE RESTRICT, FOREIGN KEY(branch_id) REFERENCES branches(id) ON DELETE SET NULL, FOREIGN KEY(booking_id) REFERENCES bookings(id) ON DELETE RESTRICT, FOREIGN KEY(vehicle_id) REFERENCES vehicles(id) ON DELETE RESTRICT, FOREIGN KEY(driver_id) REFERENCES drivers(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS invoices (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, company_id BIGINT UNSIGNED NOT NULL, branch_id BIGINT UNSIGNED, trip_id BIGINT UNSIGNED NOT NULL UNIQUE, booking_id BIGINT UNSIGNED NOT NULL, customer_id BIGINT UNSIGNED NOT NULL, invoice_number VARCHAR(40) NOT NULL, invoice_date DATE NOT NULL, due_date DATE, status VARCHAR(24) NOT NULL DEFAULT 'issued', customer_snapshot JSON NOT NULL, pricing_snapshot JSON NOT NULL, subtotal DECIMAL(14,2) NOT NULL, discount_amount DECIMAL(14,2) NOT NULL, tax_amount DECIMAL(14,2) NOT NULL, total_amount DECIMAL(14,2) NOT NULL, UNIQUE KEY uq_invoice_no(company_id,invoice_number), FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE RESTRICT, FOREIGN KEY(branch_id) REFERENCES branches(id) ON DELETE SET NULL, FOREIGN KEY(trip_id) REFERENCES trips(id) ON DELETE RESTRICT, FOREIGN KEY(booking_id) REFERENCES bookings(id) ON DELETE RESTRICT, FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS invoice_items (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, invoice_id BIGINT UNSIGNED NOT NULL, description VARCHAR(190) NOT NULL, amount DECIMAL(14,2) NOT NULL, discount_amount DECIMAL(14,2) NOT NULL DEFAULT 0, tax_rate_percent DECIMAL(5,2) DEFAULT 0, tax_amount DECIMAL(14,2) NOT NULL DEFAULT 0, line_total DECIMAL(14,2) NOT NULL, FOREIGN KEY(invoice_id) REFERENCES invoices(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS payments (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, company_id BIGINT UNSIGNED NOT NULL, branch_id BIGINT UNSIGNED, invoice_id BIGINT UNSIGNED NOT NULL, receipt_number VARCHAR(40) NOT NULL, amount DECIMAL(14,2) NOT NULL, method VARCHAR(24) NOT NULL, reference VARCHAR(120), transaction_id VARCHAR(160), status VARCHAR(24) NOT NULL DEFAULT 'posted', received_at DATETIME NOT NULL, created_by BIGINT UNSIGNED, UNIQUE KEY uq_receipt(company_id,receipt_number), UNIQUE KEY uq_transaction(company_id,transaction_id), FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE RESTRICT, FOREIGN KEY(branch_id) REFERENCES branches(id) ON DELETE SET NULL, FOREIGN KEY(invoice_id) REFERENCES invoices(id) ON DELETE RESTRICT, FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS payment_refunds (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, payment_id BIGINT UNSIGNED NOT NULL, amount DECIMAL(14,2) NOT NULL, method VARCHAR(24) NOT NULL, reason TEXT NOT NULL, refunded_at DATETIME NOT NULL, created_by BIGINT UNSIGNED, FOREIGN KEY(payment_id) REFERENCES payments(id) ON DELETE RESTRICT, FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS expenses (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, company_id BIGINT UNSIGNED NOT NULL, branch_id BIGINT UNSIGNED, vendor_id BIGINT UNSIGNED, category VARCHAR(32) NOT NULL, description VARCHAR(190) NOT NULL, amount DECIMAL(14,2) NOT NULL, tax_amount DECIMAL(14,2) NOT NULL DEFAULT 0, expense_date DATE NOT NULL, expense_number VARCHAR(40) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'submitted', receipt_path VARCHAR(255), created_by BIGINT UNSIGNED, approved_by BIGINT UNSIGNED, approved_at DATETIME, approval_note TEXT, UNIQUE KEY uq_expense_no(company_id,expense_number), FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE RESTRICT, FOREIGN KEY(branch_id) REFERENCES branches(id) ON DELETE SET NULL, FOREIGN KEY(vendor_id) REFERENCES vendors(id) ON DELETE SET NULL, FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL, FOREIGN KEY(approved_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS maintenance_orders (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, company_id BIGINT UNSIGNED NOT NULL, branch_id BIGINT UNSIGNED, vehicle_id BIGINT UNSIGNED NOT NULL, vendor_id BIGINT UNSIGNED, order_number VARCHAR(40) NOT NULL, maintenance_type VARCHAR(40) NOT NULL, status VARCHAR(24) NOT NULL DEFAULT 'scheduled', scheduled_start DATETIME NOT NULL, expected_end DATETIME, completed_at DATETIME, odometer_km DECIMAL(12,1), description VARCHAR(255) NOT NULL, work_performed TEXT, cost DECIMAL(14,2) DEFAULT 0, UNIQUE KEY uq_maintenance_no(company_id,order_number), FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE RESTRICT, FOREIGN KEY(branch_id) REFERENCES branches(id) ON DELETE SET NULL, FOREIGN KEY(vehicle_id) REFERENCES vehicles(id) ON DELETE RESTRICT, FOREIGN KEY(vendor_id) REFERENCES vendors(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS accounts (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, company_id BIGINT UNSIGNED NOT NULL, code VARCHAR(24) NOT NULL, name VARCHAR(120) NOT NULL, type VARCHAR(20) NOT NULL, normal_side VARCHAR(8) NOT NULL, is_active BOOLEAN NOT NULL DEFAULT TRUE, UNIQUE KEY uq_account_code(company_id,code), FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS journal_entries (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, company_id BIGINT UNSIGNED NOT NULL, branch_id BIGINT UNSIGNED, journal_number VARCHAR(40) NOT NULL, source_type VARCHAR(80) NOT NULL, source_id BIGINT UNSIGNED NOT NULL, event VARCHAR(40) NOT NULL, entry_date DATE NOT NULL, memo VARCHAR(255) NOT NULL, total_debit DECIMAL(16,2) NOT NULL, total_credit DECIMAL(16,2) NOT NULL, status VARCHAR(16) NOT NULL DEFAULT 'posted', created_by BIGINT UNSIGNED, UNIQUE KEY uq_journal_no(company_id,journal_number), UNIQUE KEY uq_journal_source(company_id,source_type,source_id,event), FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE RESTRICT, FOREIGN KEY(branch_id) REFERENCES branches(id) ON DELETE SET NULL, FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS journal_lines (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, journal_entry_id BIGINT UNSIGNED NOT NULL, account_id BIGINT UNSIGNED NOT NULL, description VARCHAR(190) NOT NULL, debit DECIMAL(16,2) NOT NULL DEFAULT 0, credit DECIMAL(16,2) NOT NULL DEFAULT 0, FOREIGN KEY(journal_entry_id) REFERENCES journal_entries(id) ON DELETE RESTRICT, FOREIGN KEY(account_id) REFERENCES accounts(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS audit_logs (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, company_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED, event VARCHAR(100) NOT NULL, subject_type VARCHAR(120), subject_id BIGINT UNSIGNED, before_values JSON, after_values JSON, ip_address VARCHAR(45), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX ix_audit_company_time(company_id,created_at), FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE RESTRICT, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS notifications (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, company_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, title VARCHAR(160) NOT NULL, message VARCHAR(500) NOT NULL, href VARCHAR(255), read_at DATETIME, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX ix_notification_user(user_id,read_at,created_at), FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE RESTRICT, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
